"""Generates the written deliverables from reports/metrics_*.json so docs never drift from results."""

from __future__ import annotations

import json
from pathlib import Path

import pandas as pd

from . import config as C
from . import features as F
from .stability import monitoring_plan
from .utils import md_table

SYN_NOTE = (
    "> **Read this first:** every number below comes from the **synthetic stand-in dataset** generated by "
    "`credit_risk.synthetic` (same columns and quirks as Home Credit, but fake people). It proves the pipeline works "
    "end to end; it says nothing about real borrowers. Re-run on the real Kaggle data (`CR_DATA_SOURCE=real`) "
    "and regenerate these documents with `make docs` before quoting any figure."
)


def load(reports_dir: Path | None = None) -> dict[str, dict]:
    d = Path(reports_dir or C.REPORTS)
    out = {}
    for s in "AB":
        f = d / f"metrics_{s}.json"
        if f.exists():
            out[s] = json.loads(f.read_text())
    return out


def _df(x) -> pd.DataFrame:
    return pd.DataFrame(x)


def _banner(m: dict) -> str:
    return (
        SYN_NOTE
        if m.get("source") == "synthetic"
        else "> Results computed on the real Home Credit Default Risk data."
    )


def _ci(d: dict, key: str) -> str:
    lo, hi = d[key]
    return f"[{lo:.3f}, {hi:.3f}]"


# ---------------------------------------------------------------------------------------------
def write_data_audit(m: dict, path: Path) -> None:
    a = m["audit"]
    miss = _df([{"column": k, "missing_share": v} for k, v in a["missing_top15"].items()])
    txt = f"""# Data audit

{_banner(m)}

## Basics
| Item | Value |
|---|---|
| Rows (applications) | {a["rows"]:,} |
| Columns (raw) | {a["columns"]} |
| Target rate (TARGET = 1, payment difficulties) | {a["target_rate"]:.2%} |
| Imbalance (good : bad) | {a["imbalance_ratio"]:.1f} : 1 |
| `SK_ID_CURR` unique | {a["id_unique"]} |
| Duplicate rows (excluding ID) | {a["duplicate_rows"]} |

## Missingness
{len(a["missing_over_50pct"])} columns have more than 50% missing values. Top 15 columns by missing share:

{md_table(miss, ".1%")}

Missing external scores are treated as **information** (explicit `*_MISSING` flags; trees handle NaN natively;
the scorecard gives missing its own WoE bin).

## Sentinels and impossible values
| Check | Finding | Treatment |
|---|---|---|
| `DAYS_EMPLOYED == 365243` | {a["sentinel_days_employed"]:,} rows | -> NaN plus `DAYS_EMPLOYED_ANOM` flag |
| `XNA` categories | {json.dumps(a["xna_counts"])} | -> NaN (unknown) |
| Income <= 0 | {a["negative_income"]} rows | -> NaN |
| Age range (from `DAYS_BIRTH`) | {a["age_range"][0]:.0f}-{a["age_range"][1]:.0f} years | Days fields are negative: age = -DAYS_BIRTH / 365.25 |

## Leakage review
* Stage A uses only fields known at application time.
* Stage B aggregates only records dated **before** the application (relative days <= 0, monthly balances < 0);
  enforced by `features.before_application` and unit-tested.
* All binning, imputation grouping and encoders are fit on **train only**; the test set is touched once for final numbers.
* A single-feature AUC or IV that looks too good (IV > 0.5, model AUC near 0.9) is treated as a leakage alarm, not a success.

## Categorical cardinality
{md_table(_df([{"column": k, "distinct_values": v} for k, v in sorted(a["cardinality"].items(), key=lambda kv: -kv[1])]), ".0f")}

## Policy decisions
* `CODE_GENDER` is **never** a model input. Age-derived features are excluded by default (`CR_ALLOW_AGE=0`).
  Both are still used to **audit outcomes** by group.
* Rare categories (< 1% of train) are grouped into `{F.RARE_LABEL}`.
"""
    Path(path).write_text(txt)


def write_feature_dictionary(path: Path) -> None:
    rows = [
        {"feature": k, "how computed": v[0], "why it should matter": v[1]}
        for k, v in F.FEATURE_DICTIONARY.items()
    ]
    Path(path).write_text(
        "# Feature dictionary (engineered features)\n\nRaw columns follow `HomeCredit_columns_description`.\n\n"
        + md_table(_df(rows))
        + "\n"
    )


def write_monitoring_plan(path: Path) -> None:
    Path(path).write_text(
        "# Monitoring plan\n\nThresholds are conventions to be agreed with the model-risk owner.\n\n"
        + md_table(monitoring_plan())
        + "\n"
    )


def write_results(ms: dict[str, dict], path: Path) -> None:
    mA = ms["A"]
    parts = [f"# Results\n\n{_banner(mA)}\n"]
    for s, m in ms.items():
        sc, g = m["scorecard"], m["gbm"]
        parts.append(
            f"\n## Stage {s}: {'application_train only' if s == 'A' else 'application + history tables'}\n"
        )
        t = _df(
            [
                {
                    "model": "Scorecard (WoE + logistic)",
                    **{k: sc["test"][k] for k in ("auc", "gini", "ks", "pr_auc", "brier")},
                },
                {
                    "model": f"LightGBM (calibrated: {m['calibration']['chosen']})",
                    **{k: g["test"][k] for k in ("auc", "gini", "ks", "pr_auc", "brier")},
                },
                {
                    "model": "XGBoost (comparison, raw)",
                    **{k: m["xgboost"]["test"][k] for k in ("auc", "gini", "ks", "pr_auc", "brier")},
                }
                if "test" in m["xgboost"]
                else {"model": "XGBoost", "auc": float("nan")},
            ]
        )
        parts.append("**Test-set performance**\n\n" + md_table(t) + "\n")
        parts.append(
            f"\n95% bootstrap CI (test): scorecard AUC {_ci(sc['test_ci'], 'auc')}, KS {_ci(sc['test_ci'], 'ks')}; "
            f"LightGBM AUC {_ci(g['test_ci'], 'auc')}, KS {_ci(g['test_ci'], 'ks')}.\n"
        )
        parts.append(
            "\n**Imbalance handling (validation)**\n\n"
            + md_table(_df(m["imbalance_comparison"])[["strategy", "auc", "pr_auc", "brier", "mean_pred"]])
            + "\n"
        )
        parts.append(
            "\n**Calibration (test, calibrators fit on validation)**\n\n"
            + md_table(
                _df(m["calibration"]["table"])[["model", "method", "brier", "ece", "mean_pred"]], ".4f"
            )
            + "\n"
        )
        parts.append(
            "\nClass-weighted LightGBM arm (the classic over-prediction case):\n\n"
            + md_table(_df(m["calibration"]["class_weight_arm"]), ".4f")
            + "\n"
        )
        b = m["business"]
        parts.append(
            f"\n**Business cut-off** (assumptions are illustrative: margin {b['assumptions']['margin_rate']:.0%}, LGD {b['assumptions']['lgd']:.0%}). "
            f"Cut-off chosen on validation: PD <= {b['cutoff_pd']:.3f}. On the test set: approval rate {b['test']['approval_rate']:.1%}, "
            f"bad rate among approved {b['test']['bad_rate_approved']:.2%}, profit {b['test']['profit']:,.0f} vs approve-all "
            f"{b['baselines_test']['approve_all']:,.0f} "
            f"({'n/a' if b['uplift_vs_approve_all_pct'] is None else format(b['uplift_vs_approve_all_pct'], '+.1%')} vs approve-all, simulation only).\n"
        )
        parts.append(
            "\n**Sensitivity of the best cut-off (validation)**\n\n"
            + md_table(
                _df(b["sensitivity"])[["lgd_change", "margin_change", "best_approval_rate", "best_pd_cutoff"]]
            )
            + "\n"
        )
        parts.append(
            "\n**Score bands (test; band 1 = riskiest)**\n\n"
            + md_table(
                _df(b["score_bands"])[
                    [
                        "band",
                        "score_min",
                        "score_max",
                        "applicants",
                        "bad_rate",
                        "lift",
                        "cum_approval_rate",
                        "cum_bad_rate",
                    ]
                ],
                ".3f",
            )
            + "\n"
        )
        st = m["stability"]
        parts.append(
            f"\n**Stability:** score PSI validation vs test = {st['score_psi_valid_vs_test']:.4f}; shifted-population exercise "
            f"(applicants under 35) score PSI = {st['shift_exercise_young_vs_all']['score_psi']:.3f}.\n"
        )
        for name, f in m["fairness"].items():
            parts.append(
                f"\n**Fairness by {name}** (gaps: approval {f['gaps']['approval_rate_gap']:.3f}, disparate-impact ratio "
                f"{f['gaps']['disparate_impact_ratio']:.3f}, four-fifths flag {f['gaps']['four_fifths_rule_flag']})\n\n"
                + md_table(_df(f["table"]), ".3f")
                + "\n"
            )
        parts.append("\n**Three example applicants (test set)**\n")
        for ex in m["explain"]["examples"]:
            rc = (
                "; ".join(f"{r['reason']} (+{r['impact_log_odds']:.2f})" for r in ex["reason_codes"])
                or "none"
            )
            parts.append(f"* **{ex['label']}** - PD {ex['pd']:.1%}, score {ex['score']:.0f}. Reasons: {rc}\n")
    if "B" in ms:
        a, b = ms["A"], ms["B"]
        t = _df(
            [
                {
                    "model": "Scorecard",
                    "A auc": a["scorecard"]["test"]["auc"],
                    "B auc": b["scorecard"]["test"]["auc"],
                    "A ks": a["scorecard"]["test"]["ks"],
                    "B ks": b["scorecard"]["test"]["ks"],
                },
                {
                    "model": "LightGBM",
                    "A auc": a["gbm"]["test"]["auc"],
                    "B auc": b["gbm"]["test"]["auc"],
                    "A ks": a["gbm"]["test"]["ks"],
                    "B ks": b["gbm"]["test"]["ks"],
                },
            ]
        )
        parts.append("\n## Stage A vs Stage B (value of the extra tables)\n\n" + md_table(t) + "\n")
    Path(path).write_text("".join(parts))


def write_model_card(ms: dict[str, dict], path: Path) -> None:
    m = ms["A"]
    mb = ms.get("B")
    sc, g, b = m["scorecard"], m["gbm"], m["business"]
    fair = m["fairness"]
    gender_gap = fair.get("gender", {}).get("gaps", {})
    age_gap = fair.get("age_band", {}).get("gaps", {})
    stage_b = ""
    if mb:
        stage_b = (
            f"\n| Stage B (all tables) | LightGBM test AUC {mb['gbm']['test']['auc']:.3f}, KS {mb['gbm']['test']['ks']:.3f}; "
            f"scorecard AUC {mb['scorecard']['test']['auc']:.3f} |"
        )
    txt = f"""# Model card: Credit risk scoring (PD model)

{_banner(m)}

**Version:** {m["version"]} | **Date:** {pd.Timestamp.now(tz="UTC").strftime("%Y-%m-%d")} | **Status:** educational demonstration

## 1. Purpose and intended use
Estimate the **probability of default (PD)** for a loan application at decision time, convert it to a score,
give plain-English reasons, and support an approve/decline cut-off chosen on expected profit.
Intended for portfolio/learning use and as a template for how a risk team documents a model.

## 2. Out-of-scope use
Not a production lending system and not financial advice. Not validated for any real lender, product, country or period;
no legal, RBI/digital-lending or fair-lending compliance review has been performed. Must not be used for individual
credit decisions. Not suitable for pricing, limit setting or loss provisioning without LGD/EAD models.

## 3. Data
* Source: Home Credit Default Risk (Kaggle competition data; license/rules apply, raw data is not redistributed here).
* This build: **{m["source"]}** data, {m["split"]["train"] + m["split"]["valid"] + m["split"]["test"]:,} applications,
  default rate {m["split"]["default_rate"][0]:.2%} (train).
* Target: client had payment difficulties (TARGET = 1).
* Split: stratified 60/20/20 with fixed seed {C.SEED}; test set used once for final numbers.
* No application date exists, so no out-of-time validation (limitation).

## 4. Preprocessing
Sentinel `DAYS_EMPLOYED = 365243` -> NaN + flag; `XNA` -> NaN; negative day counts converted to years; ratios
(payment burden, loan/income, loan/goods); missing-score flags; rare categories grouped on train only.
Features used: {m["n_features"]}. Excluded by policy: {", ".join(m["excluded_by_policy"])}.

## 5. Models compared
| Model | Role |
|---|---|
| WoE scorecard (monotone binning, logistic regression; IV 0.02-0.5 and |corr| < {C.CORR_MAX}; {sc["report"]["n_final"]} final variables) | Interpretable, regulator-friendly baseline |
| LightGBM (imbalance strategy: {g["imbalance_strategy"]}; {m["n_trials"]} Optuna trials; early stopping) | Challenger, then calibrated ({m["calibration"]["chosen"]}) |
| XGBoost | Comparison only |

Scorecard scaling: base score {sc["base_score"]} at good:bad odds {sc["base_odds"]}:1, {sc["pdo"]} points to double the odds.

## 6. Performance (test set, 95% bootstrap CI)
| | AUC | Gini | KS | PR-AUC | Brier |
|---|---|---|---|---|---|
| Scorecard | {sc["test"]["auc"]:.3f} {_ci(sc["test_ci"], "auc")} | {sc["test"]["gini"]:.3f} | {sc["test"]["ks"]:.3f} {_ci(sc["test_ci"], "ks")} | {sc["test"]["pr_auc"]:.3f} | {sc["test"]["brier"]:.4f} |
| LightGBM (calibrated) | {g["test"]["auc"]:.3f} {_ci(g["test_ci"], "auc")} | {g["test"]["gini"]:.3f} | {g["test"]["ks"]:.3f} {_ci(g["test_ci"], "ks")} | {g["test"]["pr_auc"]:.3f} | {g["test"]["brier"]:.4f} |
{stage_b and "| Stage | Result |" + chr(10) + "|---|---|" + stage_b}

A gap of a few thousandths of AUC between scorecard and GBM is not evidence that the GBM is better;
see the confidence intervals. Anything near AUC 0.9 on this kind of data should be investigated for leakage.

## 7. Calibration
Calibrator chosen by 2-fold cross-fitting on the validation set, fit on validation, evaluated on test.

{md_table(_df(m["calibration"]["table"])[["model", "method", "brier", "ece", "mean_pred"]], ".4f")}

## 8. Explainability
TreeSHAP on LightGBM (global summary + dependence plots in `reports/figures/`). Per-applicant **reason codes** = the top
features pushing risk up, mapped to customer-friendly sentences (`explain.REASON_CODES`) and de-duplicated.
Rank agreement between mean |SHAP| and scorecard IV: Spearman {m["explain"]["spearman_shap_vs_iv"]:.2f}.
SHAP explains the model, not causation.

## 9. Fairness
Audited by gender, age band and family status at the chosen cut-off (gender is not a model input; proxies can still leak).
* Gender: approval-rate gap {gender_gap.get("approval_rate_gap", float("nan")):.3f}, disparate-impact ratio {gender_gap.get("disparate_impact_ratio", float("nan")):.3f}, four-fifths flag {gender_gap.get("four_fifths_rule_flag")}.
* Age band: approval-rate gap {age_gap.get("approval_rate_gap", float("nan")):.3f}, disparate-impact ratio {age_gap.get("disparate_impact_ratio", float("nan")):.3f}, four-fifths flag {age_gap.get("four_fifths_rule_flag")}.
Group-specific thresholds are legally sensitive and are not applied. Remaining gaps may reflect real risk differences,
proxies, or sample noise in small groups; they should be reviewed by compliance before any real use.

## 10. Business cut-off (illustrative economics)
{md_table(pd.DataFrame(b["assumptions"], index=[0]).T.reset_index().rename(columns={"index": "assumption", 0: "value"}), ".2f")}

Cut-off chosen on validation: approve if PD <= {b["cutoff_pd"]:.3f}. Test: approval {b["test"]["approval_rate"]:.1%},
bad rate among approved {b["test"]["bad_rate_approved"]:.2%}. Profit vs approve-all is a **simulation** driven by these
assumptions; see the +/-20% sensitivity table in `reports/results_*.md`.

## 11. Limitations
Single lender and country; old data; no macro-economic information; labels only exist for **approved** applicants
(selection bias, no reject inference); no application date so no out-of-time test; calibration is only as good as the
development population; synthetic numbers (if present) are not evidence of real performance; LGD and margin are assumed.

## 12. Monitoring
See `docs/monitoring_plan.md`: score/feature PSI, approval rate, bad rate by cohort, calibration, AUC/KS on matured cohorts,
fairness, data quality. PSI thresholds 0.10 / 0.25 are conventions.

## 13. Ethical considerations
Credit decisions affect people's lives. Use human review for borderline cases, give adverse-action reasons, keep audit
logs without personal data, and re-audit fairness at each retrain. Check current RBI digital-lending and fair-practice
guidance before any real deployment.
"""
    Path(path).write_text(txt)


def write_business_summary_pdf(ms: dict[str, dict], path: Path) -> None:
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import cm
    from reportlab.platypus import Image, Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle

    m = ms["A"]
    mb = ms.get("B", m)
    sc, g, b = m["scorecard"], m["gbm"], m["business"]
    st = getSampleStyleSheet()
    body = ParagraphStyle("b", parent=st["Normal"], fontSize=9, leading=12)
    small = ParagraphStyle(
        "s", parent=st["Normal"], fontSize=7.5, leading=9.5, textColor=colors.HexColor("#8a1c1c")
    )
    h = ParagraphStyle("h", parent=st["Heading3"], fontSize=11, spaceBefore=6, spaceAfter=2)
    doc = SimpleDocTemplate(
        str(path),
        pagesize=A4,
        leftMargin=1.6 * cm,
        rightMargin=1.6 * cm,
        topMargin=1.3 * cm,
        bottomMargin=1.2 * cm,
    )
    S = []
    S.append(Paragraph("Credit Risk Scoring - 1-page business summary", st["Title"]))
    if m.get("source") == "synthetic":
        S.append(
            Paragraph(
                "NOTE: figures come from a SYNTHETIC stand-in dataset and demonstrate the pipeline only. Re-run on the real data before quoting.",
                small,
            )
        )
    S.append(Paragraph("Problem", h))
    S.append(
        Paragraph(
            "A lender must decide whom to approve and how risky each applicant is. We estimate each applicant's probability of default (PD), "
            "explain it in plain language, and pick the approval cut-off that maximises simulated profit.",
            body,
        )
    )
    S.append(Paragraph("Approach", h))
    S.append(
        Paragraph(
            "A traditional WoE/logistic <b>scorecard</b> (interpretable baseline) and a <b>LightGBM</b> challenger, probabilities <b>calibrated</b> so "
            "that a 10% PD means roughly 10 in 100 default, <b>SHAP reason codes</b>, a <b>fairness audit</b>, a <b>PSI stability</b> check, "
            "and a Dockerised <b>FastAPI</b> scoring service.",
            body,
        )
    )
    S.append(Paragraph("Headline results (test set)", h))
    rows = [
        ["Model", "AUC", "KS", "PR-AUC", "Brier"],
        [
            "Scorecard",
            f"{sc['test']['auc']:.3f}",
            f"{sc['test']['ks']:.3f}",
            f"{sc['test']['pr_auc']:.3f}",
            f"{sc['test']['brier']:.4f}",
        ],
        [
            "LightGBM (calibrated)",
            f"{g['test']['auc']:.3f}",
            f"{g['test']['ks']:.3f}",
            f"{g['test']['pr_auc']:.3f}",
            f"{g['test']['brier']:.4f}",
        ],
    ]
    if "B" in ms:
        rows.append(
            [
                "LightGBM + history tables (Stage B)",
                f"{mb['gbm']['test']['auc']:.3f}",
                f"{mb['gbm']['test']['ks']:.3f}",
                f"{mb['gbm']['test']['pr_auc']:.3f}",
                f"{mb['gbm']['test']['brier']:.4f}",
            ]
        )
    t = Table(rows, hAlign="LEFT", colWidths=[7 * cm, 2 * cm, 2 * cm, 2.2 * cm, 2.2 * cm])
    t.setStyle(
        TableStyle(
            [
                ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#e8eef7")),
                ("GRID", (0, 0), (-1, -1), 0.4, colors.grey),
                ("FONTSIZE", (0, 0), (-1, -1), 8.5),
            ]
        )
    )
    S.append(t)
    up = b["uplift_vs_approve_all_pct"]
    S.append(Spacer(1, 4))
    S.append(
        Paragraph(
            f"<b>Cut-off:</b> approve if PD &lt;= {b['cutoff_pd']:.1%} (chosen on validation data). On the test set this approves {b['test']['approval_rate']:.0%} of applicants "
            f"with a {b['test']['bad_rate_approved']:.1%} bad rate among approved, vs {m['split']['default_rate'][2]:.1%} overall. Simulated profit is "
            f"{'n/a' if up is None else format(up, '+.0%')} vs approving everyone, under <i>illustrative</i> assumptions (margin {b['assumptions']['margin_rate']:.0%} of loan, "
            f"LGD {b['assumptions']['lgd']:.0%}). The riskiest 20% of applicants contain {b['riskiest_20pct_capture']:.0%} of all defaults.",
            body,
        )
    )
    fig = Path(C.FIGURES) / "profit_A.png"
    fig2 = Path(C.FIGURES) / "reliability_A.png"
    imgs = [Image(str(f), width=8.2 * cm, height=5.6 * cm) for f in (fig, fig2) if f.exists()]
    if imgs:
        S.append(Spacer(1, 4))
        S.append(Table([imgs], hAlign="LEFT"))
    S.append(Paragraph("Risks and limits", h))
    S.append(
        Paragraph(
            "Economics are assumptions, so the profit figure is a simulation, not a forecast. Labels exist only for previously approved applicants "
            "(selection bias). No out-of-time test. Fairness gaps by gender/age must be reviewed by compliance. Not a production lending system.",
            body,
        )
    )
    S.append(Paragraph("Recommendation", h))
    S.append(
        Paragraph(
            "Use the scorecard as the governed baseline and the calibrated GBM as challenger; run both in shadow mode, monitor PSI/bad rate monthly, "
            "and only move to production after validation on real, recent, out-of-time data and a compliance review.",
            body,
        )
    )
    doc.build(S)


def draw_architecture(path: Path) -> None:
    import matplotlib

    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    from matplotlib.patches import FancyBboxPatch

    fig, ax = plt.subplots(figsize=(11, 6.2))
    ax.axis("off")
    ax.set_xlim(0, 11)
    ax.set_ylim(0, 6.2)

    def box(x, y, w, h, text, fc="#e8eef7"):
        ax.add_patch(FancyBboxPatch((x, y), w, h, boxstyle="round,pad=0.04", fc=fc, ec="#34495e", lw=1))
        ax.text(x + w / 2, y + h / 2, text, ha="center", va="center", fontsize=8.5)

    def arrow(x1, y1, x2, y2):
        ax.annotate("", xy=(x2, y2), xytext=(x1, y1), arrowprops=dict(arrowstyle="->", color="#34495e"))

    box(0.2, 5.2, 2.6, 0.7, "Kaggle raw files\n(or synthetic look-alike)")
    box(3.4, 5.2, 3.2, 0.7, "Data audit + cleaning\n(sentinels, XNA, types, flags)")
    box(7.2, 5.2, 3.5, 0.7, "Feature engineering\nStage A ratios / flags;  Stage B aggregates")
    arrow(2.8, 5.55, 3.4, 5.55)
    arrow(6.6, 5.55, 7.2, 5.55)
    box(1.2, 3.9, 4.0, 0.8, "Scorecard path\nbinning -> WoE -> logistic -> points", "#fdf2d9")
    box(6.0, 3.9, 4.6, 0.8, "ML path\nLightGBM / XGBoost -> Optuna -> calibration", "#fdf2d9")
    arrow(8.9, 5.2, 3.2, 4.7)
    arrow(8.9, 5.2, 8.3, 4.7)
    box(
        2.2, 2.7, 6.6, 0.7, "Evaluation: AUC | KS | Gini | PR-AUC | Brier | lift  (MLflow tracked)", "#e3f4e8"
    )
    arrow(3.2, 3.9, 4.5, 3.4)
    arrow(8.3, 3.9, 6.5, 3.4)
    for i, t in enumerate(["SHAP\nreason codes", "Profit\ncut-off", "Fairness\naudit", "PSI /\nmonitoring"]):
        box(0.6 + i * 2.6, 1.45, 2.2, 0.8, t, "#f6e3e3")
        arrow(5.5, 2.7, 1.7 + i * 2.6, 2.25)
    box(
        2.4,
        0.25,
        6.2,
        0.75,
        "Model bundle -> FastAPI /score (Docker)\nModel card + business summary",
        "#e3e8f9",
    )
    for i in range(4):
        arrow(1.7 + i * 2.6, 1.45, 5.5, 1.0)
    fig.tight_layout()
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(path, dpi=140)
    plt.close(fig)
